-- Sports (id: 1=Hockey, 2=Football, 3=Basketball)

-- Roles Hockey (id: 1=Milieu, 2=Attaquant, 3=Défenseur)

-- Equipment Hockey (id: 1-14)

-- Goals Hockey (id: 1-5)

-- =============================================
-- UTILISATEURS
-- =============================================

-- =============================================
-- EXERCICES HOCKEY (20 exercices représentatifs)
-- =============================================

-- 1. Slalom balle simple
VALUES ('Slalom balle simple', 'Dispose 5 à 7 plots en ligne, espacés de 1,5 à 2 m. Dribble la balle entre les plots en gardant la tête levée. Contrôle la balle à chaque changement de direction.', 5, 3, '5 allers-retours', 1, 'MOYENNE');

-- 2. Tir en pivot
VALUES ('Tir en pivot', 'Place un plot ou repère à 3 m. Dribble vers le plot, effectue un pivot complet sur toi-même et tire au but ou sur un mur.', 5, 3, '10 tirs', 1, 'ELEVEE');

-- 3. Sprint 20m
VALUES ('Sprint 20m', 'Trace une ligne de 20 m. Sprint en ligne droite, récupère en marchant.', 3, 6, '30 s', 1, 'ELEVEE', 'data:image/gif;base64,');

-- 4. Slalom avec crosse
VALUES ('Slalom avec crosse', 'Dispose 5 plots en ligne, espacés de 2 m. Dribble uniquement avec la crosse entre les plots, garde la tête levée.', 5, 3, '5 allers-retours', 1, 'MOYENNE');

-- 5. Course en endurance
VALUES ('Course en endurance', 'Choisis une distance de 400 à 800 m. Courir à rythme constant, respiration régulière.', 15, 3, '1 course', 1, 'MOYENNE');

-- 6. Tir en mouvement
VALUES ('Tir en mouvement', 'Dribble 5-10 m puis tire sur cible ou mur. Concentre-toi sur la précision après le mouvement.', 5, 3, '8 tirs', 1, 'ELEVEE');

-- 7. Pompes sur ballon
VALUES ('Pompes sur ballon', 'Place tes mains sur un ballon de fitness. Réalise des pompes classiques en gardant le corps droit et gainé.', 5, 3, '10-15 répétitions', 1, 'MOYENNE');

-- 8. Passes longues en mouvement
VALUES ('Passes longues en mouvement', 'Place un mur ou rebondisseur à 5-8 m. Passe la balle en mouvement, réceptionne et renvoie.', 5, 3, '10 passes', 1, 'MOYENNE');

-- 9. Agilité sur plots
VALUES ('Agilité sur plots', 'Dispose 4-6 plots en carré ou zig-zag. Déplace-toi rapidement autour en changeant de direction, genoux légèrement fléchis.', 5, 4, '20 s', 1, 'MOYENNE');

-- 10. Dribble avec changements
VALUES ('Dribble avec changements', 'Dribble sur 5-10 m, change brusquement de direction à un plot. Concentre-toi sur le contrôle à chaque changement.', 5, 3, '5 allers-retours', 1, 'MOYENNE');

-- 11. Squat jump
VALUES ('Squat jump', 'En position de squat, saute verticalement, atterrissage contrôlé. Concentre-toi sur l''amplitude du saut.', 5, 3, '10-15 répétitions', 1, 'ELEVEE');

-- 12. Course fractionnée
VALUES ('Course fractionnée', 'Sprint 20 m, récupère 30 s, alterne vitesse maximale et récupération active.', 10, 6, '30 s', 1, 'ELEVEE');

-- 13. Stickhandling rapide
VALUES ('Stickhandling rapide', 'Place un plot. Dribble rapidement autour, alternant mains et directions sans perdre le contrôle de la balle.', 5, 4, '30 s', 1, 'ELEVEE');

-- 14. Tir penalty
VALUES ('Tir penalty', 'Place-toi sur la ligne de penalty. Contrôle la balle avant de tirer en visant des cibles dans le but ou sur mur.', 5, 3, '10 tirs', 1, 'MOYENNE');

-- 15. Sprint + passe
VALUES ('Sprint + passe', 'Sprint 10 m, effectue une passe au mur ou rebondisseur, récupère la balle et répète.', 5, 3, '10 passes', 1, 'ELEVEE');

-- 16. Fente latérale
VALUES ('Fente latérale', 'Fente sur le côté, genou plié à 90°, maintiens la balle sous contrôle, alterne côtés.', 5, 3, '10 par jambe', 1, 'MOYENNE');

-- 17. Pompes classiques
VALUES ('Pompes classiques', 'Réalise des pompes au sol, corps bien droit, mains sous les épaules.', 5, 3, '10-15 répétitions', 1, 'MOYENNE');

-- 18. Sprint latéral
VALUES ('Sprint latéral', 'Déplace-toi latéralement sur 10 m, retour en marchant ou jogging léger. Pieds rapides, genoux fléchis.', 5, 4, '30 s', 1, 'ELEVEE');

-- 19. Sprint + tir
VALUES ('Sprint + tir', 'Sprint 10 m, dribble et tire sur cible ou mur. Concentre-toi sur précision et explosivité.', 5, 3, '10 répétitions', 1, 'ELEVEE');

-- 20. Passes sous pression
VALUES ('Passes sous pression', 'Place un mur ou rebondisseur à 2-3 m. Effectue des passes rapides au sol, contrôle et renvoie sans perdre rythme.', 5, 3, '20 passes', 1, 'MOYENNE');

-- 21. Gainage planche
VALUES ('Gainage planche', 'Position de planche sur les avant-bras, corps aligné de la tête aux talons. Maintiens la position en contractant les abdominaux et les fessiers.', 5, 3, '45 s', 1, 'FAIBLE');

-- 22. Corde à sauter
VALUES ('Corde à sauter', 'Saute à la corde à rythme régulier, pieds joints ou alternés. Garde les coudes près du corps et les poignets souples.', 8, 4, '60 s', 1, 'MOYENNE');

-- 23. Échelle d''agilité pieds rapides
VALUES ('Échelle d''agilité pieds rapides', 'Place l''échelle au sol. Traverse-la en posant les deux pieds dans chaque case le plus vite possible. Garde les genoux hauts et les bras actifs.', 5, 4, '30 s', 1, 'MOYENNE');

-- 24. Défense en reculant
VALUES ('Défense en reculant', 'Place 4 plots sur 10 m. Recule en pas chassés en gardant la crosse basse et les yeux vers l''avant. Change de direction à chaque plot.', 5, 4, '30 s', 1, 'MOYENNE');

-- 25. Interception de passe
VALUES ('Interception de passe', 'Un partenaire ou un rebondisseur envoie des balles. Positionne-toi latéralement et intercepte la balle avec la crosse, puis contrôle.', 5, 3, '10 interceptions', 1, 'MOYENNE');

-- 26. Tacle contrôlé avec crosse
VALUES ('Tacle contrôlé avec crosse', 'Simule une situation de tacle : avance vers un plot, effectue un mouvement de tacle avec la crosse à plat sur le sol, puis replace-toi rapidement.', 5, 3, '8 répétitions', 1, 'ELEVEE');

-- 27. Kettlebell swing
VALUES ('Kettlebell swing', 'Pieds écartés largeur d''épaules, balance le kettlebell entre les jambes puis propulse-le à hauteur d''épaules en poussant les hanches.', 5, 3, '15 répétitions', 1, 'ELEVEE');

-- 28. Dribble en cercle
VALUES ('Dribble en cercle', 'Place un plot au centre. Dribble autour du plot en formant des cercles, alternant le sens. Garde la balle proche de la crosse.', 5, 3, '5 cercles par sens', 1, 'FAIBLE');

-- 29. Tir en revers
VALUES ('Tir en revers', 'Place-toi à 5 m du but ou mur. Tire en utilisant le revers de ta crosse. Vise différentes zones à chaque tir.', 5, 3, '10 tirs', 1, 'ELEVEE');

-- 30. Passes courtes rapides
VALUES ('Passes courtes rapides', 'Face au mur ou rebondisseur à 2 m. Enchaîne des passes courtes au sol le plus vite possible. Contrôle et renvoie sans temps d''arrêt.', 5, 3, '30 passes', 1, 'MOYENNE');

-- 31. Saut de haies
VALUES ('Saut de haies', 'Dispose 4-6 haies espacées de 1 m. Saute par-dessus chaque haie pieds joints, atterrissage souple, enchaîne sans pause.', 5, 4, '6 passages', 1, 'ELEVEE');

-- 32. Soulevé de terre kettlebell
VALUES ('Soulevé de terre kettlebell', 'Pieds largeur d''épaules, saisis le kettlebell à deux mains. Descends en poussant les fesses en arrière, dos droit, puis remonte en contractant les fessiers.', 5, 3, '12 répétitions', 1, 'ELEVEE');

-- 33. Sprint en slalom
VALUES ('Sprint en slalom', 'Dispose 8 plots en quinconce sur 20 m. Sprinte en slalomant entre les plots le plus vite possible.', 5, 4, '4 passages', 1, 'ELEVEE');

-- 34. Élastique résistance latérale
VALUES ('Élastique résistance latérale', 'Place un élastique autour des chevilles. Fais des pas latéraux en résistant à la tension, 10 pas dans chaque direction. Maintiens les genoux fléchis.', 5, 3, '10 pas par côté', 1, 'MOYENNE');

-- 35. Tir en volée
VALUES ('Tir en volée', 'Un partenaire ou rebondisseur envoie une balle en l''air. Réceptionne et tire en un seul geste fluide sur le but ou le mur.', 5, 3, '8 tirs', 1, 'ELEVEE');

-- 36. Passe et va
VALUES ('Passe et va', 'Passe la balle au mur ou rebondisseur, sprinte 5 m vers un plot, reviens récupérer la balle et recommence.', 5, 3, '8 répétitions', 1, 'ELEVEE');

-- 37. Burpees
VALUES ('Burpees', 'Debout, descends en squat, pose les mains au sol, saute en position planche, fais une pompe, ramène les pieds et saute en l''air.', 5, 3, '10 répétitions', 1, 'ELEVEE');

-- 38. Dribble aveugle
VALUES ('Dribble aveugle', 'Dribble entre des plots en gardant la tête levée, sans regarder la balle. Développe le toucher et la proprioception.', 5, 3, '5 allers-retours', 1, 'MOYENNE');

-- 39. Défense 1 contre 1
VALUES ('Défense 1 contre 1', 'Simule une situation défensive face à un attaquant imaginaire (plot mobile). Recule, reste bas, et effectue un tacle contrôlé au bon moment.', 5, 4, '30 s', 1, 'ELEVEE');

-- 40. Étirement dynamique jambes
VALUES ('Étirement dynamique jambes', 'Enchaîne des montées de genoux, des talons-fesses, des fentes marchées et des balancements de jambes. Chaque mouvement sur 10 m.', 8, 2, '4 mouvements', 1, 'FAIBLE');

